"""Insert verified questions into nodes 3.6 and 3.7 (+2 mid +2 hard each)"""
# All answers pre-verified. Math checked independently.
# No single quote (') characters in any solution strings.
# Escaping: \\\\frac in Python -> \\frac in file -> \frac in TS -> KaTeX renders fraction
#           \\\\n   in Python -> \\n   in file -> \n   in TS -> newline

def insert_questions(filepath, questions):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    insert_point = content.rfind('];')
    assert insert_point != -1, f"Cannot find ]; in {filepath}"
    insert_text = '\n'.join(questions)
    new_content = content[:insert_point] + insert_text + '\n' + content[insert_point:]
    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(new_content)
    print(f'{filepath}: {len(questions)} questions inserted')

base = 'src/data/questions'

